mapper.select:
SELECT * FROM (
    SELECT SEM_ID AS semId, SEM_YEAR AS year, SEM_TERM AS termCode
    FROM SEMESTERS

        SEM_ID = #{semId}

    ORDER BY SEM_ID DESC
) WHERE ROWNUM = 1

SELECT COUNT(*)
FROM LECTURE_ASSIGNMENT_SUBMISSION sb
JOIN LECTURE_ASSIGNMENT asn ON asn.LEC_ASN_ID = sb.LEC_ASN_ID
JOIN LECTURE l ON l.LEC_ID = asn.LEC_ID
WHERE sb.LEC_ASN_SBM_ID = #{submissionId}
  AND sb.LEC_ASN_ID = #{assignmentId}
  AND l.LMS_PRF_ID = #{professorLmsPrfId}

SELECT COUNT(*)
FROM LECTURE_ASSIGNMENT_SUBMISSION sb
JOIN LECTURE_ASSIGNMENT asn ON asn.LEC_ASN_ID = sb.LEC_ASN_ID
JOIN LECTURE l ON l.LEC_ID = asn.LEC_ID
WHERE sb.LEC_ASN_SBM_ID = #{submissionId}
  AND l.LMS_PRF_ID = #{professorLmsPrfId}
